function _G.JAF_PanelScale(frame) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
    local us = frame and frame:FindFirstChild("JAFUIScale")
    local k = us and tonumber(us.Scale) or 1
    if not k or k <= 0.01 then k = 1 end
    return k
