    local function addBlacklistUser(username) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        username = username:match("^%s*(.-)%s*$")
        if username == "" then return end
        local lower = username:lower()
        for _, n in ipairs(BlacklistedPlayers) do if n:lower() == lower then return end end
        table.insert(BlacklistedPlayers, username)
        Config.Blacklist = BlacklistedPlayers
        SaveConfig()
        rebuildBlList()
        if refreshBlacklistUI then refreshBlacklistUI() end
        blInput.Text = ""
    end
