    local getAdminPanelSortKey; getAdminPanelSortKey = (function(plr) LPH_ATTRIBUTES(ERROR_HANDLING(false))
        if not plr or not plr.Parent then return 3, 9999, "" end
        local stealing = plr:GetAttribute("Stealing")
        local brainrotName = plr:GetAttribute("StealingIndex")
        if not stealing then return 3, 9999, plr.Name or "" end
        if brainrotName then
            for i, pName in ipairs(PRIORITY_LIST) do if pName == brainrotName then return 1, i, plr.Name or "" end end
