    end
    if _G.JAF_LiftOverObstacles ~= false then
        local _cy = cruiseYFor(0)
        local _, _legExt = _charDims()
        local _wheelClr = math.max(tonumber(_G.JAF_LiftClearance)    or 7, _legExt + 1.5)
        local _flyClr   = math.max(tonumber(_G.JAF_FlyOverClearance) or 3, _legExt + 1.5)
        local _liftCap = tonumber(_G.JAF_LiftMaxUp) or (_cy < 5 and tonumber(_G.JAF_F1LiftMaxUp)) or 14
        local _noLift = _G.JAF_NoLiftNames or { "admin" }
