        if _rem > 0.05 then
            if _rem > _ragTotal then _ragTotal = _rem end
            _stealProgress = 0
            fill.Size = UDim2.new(math.clamp(_rem / math.max(_ragTotal, 0.1), 0, 1), 0, 1, 0)
            fill.BackgroundColor3 = RAG
