        local cw = Config.TpSettings.CacheWait or 0
        if cw > 0 then task.wait(cw) end
        local waitStart = tick()
        local _poll = _G.JAF_FirstLoadPoll or 0.01
        local _lastScanned, _scanStallAt = -1, tick()
        local _waitFull = (Config.TpSettings.WaitFullScan ~= false)
        repeat task.wait(_poll)
            local _ps = _G.JAF_PlotsScanned or 0
            if _ps ~= _lastScanned then _lastScanned = _ps; _scanStallAt = tick() end
            if _G.JAF_PreWarmGrapple ~= false and _G.JAF_GrapplePreFire
               and Config.TpSettings.TpMode == "grapple" and #SharedState.AllAnimalsCache > 0 then
                local _fp   = _G.JAF_BaseFootprints
                local _wc   = LocalPlayer.Character
                local _want = tonumber(_G.JAF_PlotsTotal); if not _want or _want <= 0 then _want = 8 end
                if game:IsLoaded() and _fp and #_fp >= _want
                   and _wc and _wc:FindFirstChild("HumanoidRootPart") and _wc:FindFirstChildOfClass("Humanoid") then
                    pcall(_G.JAF_GrapplePreFire, nil, false)
