        until ((_G.JAF_PlotsTotal or 0) > 0 and (_G.JAF_PlotsScanned or 0) >= (_G.JAF_PlotsTotal or 0) and #SharedState.AllAnimalsCache > 0)
           or (not _waitFull and (
               (#SharedState.AllAnimalsCache > 0 and (_G.JAF_PlotsTotal or 0) > 0
                and (_G.JAF_PlotsScanned or 0) >= (_G.JAF_PlotsTotal or 0) - (_G.JAF_FastFireMissing or 1)
                and (tick() - _scanStallAt) > (_G.JAF_FastFireStall or 0.5))
               or ((tick() - _scanStallAt) > (_G.JAF_ScanStallTime or 3) and #SharedState.AllAnimalsCache > 0)
              ))
           or (tick()-waitStart > (_waitFull and (_G.JAF_FullScanMaxWait or 20) or (_G.JAF_FirstLoadScanWait or 12)))
        if _G.JAF_LoadReadyGate ~= false then
            local _rdT0, _rdCap = tick(), tonumber(_G.JAF_LoadReadyMax) or 8
            local _settle = tonumber(_G.JAF_LoadInvSettle) or 0.7
            local _nLast, _nAt, _sampAt = -1, tick(), 0
            local function _findTool(n) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
                if n == nil then return nil end
                local c = LocalPlayer.Character
                local t = c and c:FindFirstChild(n)
                if t then return t end
                local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
                return (bp and bp:FindFirstChild(n)) or nil
            end
            local function _toolCount() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
                local n = 0
