                if bp then for _, ch in ipairs(bp:GetChildren()) do if ch:IsA("Tool") then n = n + 1 end end end
                local c = LocalPlayer.Character
                if c then for _, ch in ipairs(c:GetChildren()) do if ch:IsA("Tool") then n = n + 1 end end end
                return n
            end
            local function _flightTool() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
                if Config.TpSettings.TpMode == "grapple" then return _findTool("Grapple Hook") end
                local t = _findTool(Config.TpSettings.Tool)
                if t then return t end
                for _, n in ipairs(_G.JAF_CarpetNames or {}) do local a = _findTool(n); if a then return a end end
                return nil
            end
            local _why = "cap"
            while tick() - _rdT0 < _rdCap do
                local _c   = LocalPlayer.Character
                local _hrp = _c and _c:FindFirstChild("HumanoidRootPart")
                local _hum = _c and _c:FindFirstChildOfClass("Humanoid")
                if game:IsLoaded() and _hrp and _hum and _hum.Health > 0
                   and LocalPlayer:FindFirstChildOfClass("Backpack") then
                    local _t  = _flightTool()
                    local _ok = _t ~= nil
                    if _ok and _t.Name == "Grapple Hook" and _G.JAF_HookReady ~= false
                       and type(getconnections) == "function" then
                        local _cok, _cs = pcall(getconnections, _t.Activated)
                        _ok = _cok and _cs ~= nil and #_cs > 0
                    end
                    if _ok and _G.JAF_LoadWaitCloner ~= false and not _findTool("Quantum Cloner") then _ok = false end
                    if _ok then _why = "ready"; break end
                    if tick() - _sampAt >= 0.1 then
                        _sampAt = tick()
                        local _n = _toolCount()
                        if _n ~= _nLast then _nLast, _nAt = _n, tick() end
                        if _n > 0 and (tick() - _nAt) > _settle then _why = "settled"; break end
                    end end
                RunService.Heartbeat:Wait()
            end
            _G.JAF_LoadReadyWhy = _why
            _G.JAF_LoadReadyMs  = math.floor((tick() - _rdT0) * 1000)
        end
        if _G.JAF_WaitStableFps then
            local _need  = _G.JAF_FpsStableFrames or 8
            local _minDt = 1 / (_G.JAF_FpsStableThresh or 30)
            local _ok, _fpsStart, _worstDt = 0, tick(), 0
            while _ok < _need and tick() - _fpsStart < (_G.JAF_LoadTpFpsWait or 3) do
                local _dt = RunService.Heartbeat:Wait()
                if _dt > _worstDt then _worstDt = _dt end
                if _dt <= _minDt then _ok = _ok + 1 else _ok = 0 end
            end
            _G.JAF_JoinFpsWaitMs = math.floor((tick() - _fpsStart) * 1000)
            _G.JAF_JoinFpsOk     = (_ok >= _need)
            _G.JAF_JoinFpsWorst  = math.floor(_worstDt * 1000)
        end
        if _G.tpToBestBrainrot then
            SharedState.FirstLoadSteal = true
            local _seqCommitted = false
            for _try = 1, (_G.JAF_FirstLoadTries or 3) do
                if #SharedState.AllAnimalsCache == 0 then
