                local _before = _hrpPos()
                local _sc = _seqCommitted
                pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
_G.tpToBestBrainrot(nil, _sc) end)
                if _G.JAF_TpStartedFlight then _seqCommitted = true end
