task.spawn(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
    local oldSS = hubFind("StealSpeedUI")
    if oldSS then oldSS:Destroy() end
    local MIN_SPEED, MAX_SPEED = 5, 31
    local stealSpeedEnabled = false
    local STEAL_SPEED = math.clamp(math.floor((tonumber(Config.StealSpeed) or 20) + 0.5), MIN_SPEED, MAX_SPEED)
    if Config.StealSpeed ~= STEAL_SPEED then Config.StealSpeed = STEAL_SPEED; SaveConfig() end
    local stealConn, _sfForce, _sfAtt, _sfMassRef = nil, nil, nil, nil
    local _sfRayParams = RaycastParams.new()
    _sfRayParams.FilterType = Enum.RaycastFilterType.Exclude
    _sfRayParams.RespectCanCollide = true
    local _sfRayChar, _sfRayCam = nil, nil
    local function _sfRemove() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        if _sfForce then pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
_sfForce:Destroy() end); _sfForce = nil end
        if _sfAtt then pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
_sfAtt:Destroy() end); _sfAtt = nil end
    end
    local function _sfBuild(hrp) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        _sfRemove()
        _sfMassRef = nil
        _sfAtt = JUI.new("Attachment", hrp, "Name", "LVAttachment")
        _sfForce = JUI.new("LinearVelocity", hrp, "Name", "SpeedForce", "Attachment0", _sfAtt, "RelativeTo", Enum.ActuatorRelativeTo.World, "VelocityConstraintMode", Enum.VelocityConstraintMode.Vector, "ForceLimitMode", Enum.ForceLimitMode.PerAxis, "MaxAxesForce", Vector3.new(math.huge, 0, math.huge), "MaxForce", math.huge, "ReactionForceEnabled", true, "VectorVelocity", Vector3.zero, "Enabled", false)
    end
    local function doDisable() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        stealSpeedEnabled = false
        if stealConn then stealConn:Disconnect(); stealConn = nil end
        _sfRemove()
    end
    local function doEnable() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        stealSpeedEnabled = true
        if stealConn then stealConn:Disconnect(); stealConn = nil end
        _sfRemove()   -- Extras-style: no LinearVelocity mover; nudge the HRP CFrame per frame instead
        stealConn = RunService.Heartbeat:Connect((function(dt) LPH_ATTRIBUTES(ERROR_HANDLING(false))
            if not SAB_LIVE() then return end
            local char = LocalPlayer.Character
            if not char then return end
            if not LocalPlayer:GetAttribute("Stealing") then return end
            if _G.JAF_DropFlingActive then return end
            local hum = char:FindFirstChildOfClass("Humanoid")
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hum or not hrp then return end
            if hum.Health <= 0 then return end
            if hum.Sit or hum:GetState() == Enum.HumanoidStateType.Climbing then return end
            local md = hum.MoveDirection
            local flat = Vector3.new(md.X, 0, md.Z)
            if flat.Magnitude <= 1e-3 then return end
            local dir = flat.Unit
            if _G.JAF_StealSpeedWallSlide ~= false then
                local _cam = Workspace.CurrentCamera
                if _sfRayChar ~= char or _sfRayCam ~= _cam then
                    _sfRayChar, _sfRayCam = char, _cam
                    _sfRayParams.FilterDescendantsInstances = { char, _cam }
                end
                local hit = Workspace:Raycast(hrp.Position, dir * (_G.JAF_StealSpeedWallLook or 2.5), _sfRayParams)
                if hit and math.abs(hit.Normal.Y) < 0.5 then
                    local n = Vector3.new(hit.Normal.X, 0, hit.Normal.Z)
                    if n.Magnitude > 1e-3 then n = n.Unit local into = dir:Dot(n) if into < 0 then dir = dir - n * into end end
                end end
            -- Extras CFrame nudge: add only the delta above the game's own WalkSpeed, along move dir
            if STEAL_SPEED > hum.WalkSpeed and dir.Magnitude > 1e-3 then
                hrp.CFrame = hrp.CFrame + (dir * (STEAL_SPEED - hum.WalkSpeed) * dt)
            end
            end)) end
