                for _, d in ipairs(plot:GetDescendants()) do if d:IsA("TextLabel") and d.Name == "Locked" then lbl = d; break end end
            end
            _lockLbls[plotName] = lbl
        end
        if not lbl then return nil, nil end
        if lbl.Visible then
            local rt = lbl.Parent and lbl.Parent:FindFirstChild("RemainingTime")
            local t = rt and tostring(rt.Text) or ""
            if t ~= "" then return t, true end
            return "?", true
        end
        return nil, false
    end
    local function _animalModelFolders() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        local rs = ReplicatedStorage
        local fs = {}
        local asc = rs:FindFirstChild("Controllers")
        asc = asc and asc:FindFirstChild("AssetStreamController")
        local cache = asc and asc:FindFirstChild("AssetCache")
        if cache then fs[#fs + 1] = cache end
        local a = rs:FindFirstChild("Animals"); if a then fs[#fs + 1] = a end
        local m = rs:FindFirstChild("Models"); m = m and m:FindFirstChild("Animals"); if m then fs[#fs + 1] = m end
        local s = rs:FindFirstChild("Assets"); s = s and s:FindFirstChild("Animals"); if s then fs[#fs + 1] = s end
        return fs
    end
    local function _findAnimalModel(name) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        if not name then return nil end
        local folders = _animalModelFolders()
        if #folders == 0 then return nil end
        local norm = (tostring(name) or ""):lower():gsub("[%s%-_]", "")
        for _, folder in ipairs(folders) do
            for _, ch in ipairs(folder:GetChildren()) do
                local cn = (ch.Name or ""):lower():gsub("[%s%-_]", "")
                if cn == norm then return ch end
            end end
        local _found
        pcall(function() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
            local AData = require(ReplicatedStorage:WaitForChild("Datas"):WaitForChild("Animals"))
            for k, v in pairs(AData) do
                if type(v) == "table" and v.DisplayName and v.DisplayName:lower() == tostring(name):lower() then
                    for _, folder in ipairs(folders) do local m = folder:FindFirstChild(k) if m then _found = m; return end end
                end end end)
        if not _found and tostring(name) ~= "" and tonumber(name) == nil then
            pcall(function() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
                local ctrls = ReplicatedStorage:FindFirstChild("Controllers")
                local ascMod = ctrls and ctrls:FindFirstChild("AssetStreamController")
                if ascMod then require(ascMod).requestAssets("m", { tostring(name) }) end
            end) end
        return _found
    end
