            end end
        RunService.Heartbeat:Connect(function(dt) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
            if not (_previewModel and _previewModel.Parent) then return end
            _previewRotation = _previewRotation + dt * 0.8
            _rotAccum = _rotAccum + dt
