            local _bestBase, _bestBaseGen, _bestRank = nil, -math.huge, math.huge
            for _, a in ipairs(SharedState.AllAnimalsCache or {}) do
                if a and a.genValue and a.owner ~= LocalPlayer.Name then
                    if _usePrio then
                        local rank = _G.JAF_PrioScore(a)
                        if rank < _bestRank or (rank == _bestRank and a.genValue > _bestBaseGen) then
                            _bestRank, _bestBaseGen, _bestBase = rank, a.genValue, a
                        end
                    elseif a.genValue > _bestBaseGen then
                        _bestBaseGen, _bestBase = a.genValue, a
                    end end end
            local function _rankOf(nm) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
                if not _usePrio or not nm then return math.huge end
                return _G.JAF_PrioScore(nm)
            end
            local _bestWalk, _bestWalkRank, _bestWalkGen = nil, math.huge, -math.huge
            for _, w in ipairs(SharedState.WalkingCache or {}) do
                if w and w.genValue then
                    local r = _rankOf(w.name)
                    if r < _bestWalkRank or (r == _bestWalkRank and w.genValue > _bestWalkGen) then
                        _bestWalkRank, _bestWalkGen, _bestWalk = r, w.genValue, w
                    end end end
            local _winner, _isCarpet
            local _carpetWins = _bestWalk and ( _bestWalkRank < _bestRank or (_bestWalkRank == _bestRank and _bestWalkGen > _bestBaseGen) )
            if _carpetWins then
                _winner = _bestWalk
                _isCarpet = true
            elseif _bestBase then
                _winner = _bestBase
                _isCarpet = false
            else
                _winner = _bestWalk
                _isCarpet = _bestWalk ~= nil
            end
            if _winner then
                if _isCarpet then
                    headerLbl.Text = "<font color='" .. _G.JAF_Rgb(Theme.Accent2) .. "'><b>CARPET BEST</b></font>"
                    pillStroke.Color = Theme.Accent2
                    pillStroke.Transparency = 0.1
                else
