                    pillStroke.Color = Theme.Accent1
                    pillStroke.Transparency = 0.3
                end
                locLbl.Text = _isCarpet and "" or ("<font color='" .. _G.JAF_Rgb(Theme.TextSecondary) .. "'>Owner</font>  <b>" .. tostring(_winner.owner or "?") .. "</b>")
                local _mut = _winner.mutation
                local _mutTxt = ""
                if not _isCarpet then
                    local _ms = ""
