                    local _ml = _ms:lower()
                    if _ms ~= "" and _ml ~= "none" and _ml ~= "n/a" and _ml ~= "nil"
                        and _ml ~= "normal" and _ml ~= "default" then
                        local _mc = _G.JAF_MutColor(_ms)
                        _mutTxt = ("  <font color='rgb(%d,%d,%d)'><b>%s</b></font>"):format(
                            math.floor(_mc.R * 255 + 0.5), math.floor(_mc.G * 255 + 0.5),
                            math.floor(_mc.B * 255 + 0.5), _ms:upper())
                    else
                        _mutTxt = "  <font color='" .. _G.JAF_Rgb(Theme.TextSecondary) .. "'>mut: none</font>"
                    end end
                nameLbl.Text = (_winner.name or "?") .. _mutTxt
                local _lockTxt = ""
                if not _isCarpet then
                    local lt, locked = _lockTextOf(_winner.plot)
                    if locked then
                        _lockTxt = "   <font color='rgb(255,95,95)'><b>" .. lt .. "</b></font>"
