                        math.floor(_rc.B * 255 + 0.5), tostring(_rar):upper())
                end
                genLbl.Text  = _genTextOf(_winner) .. _rarTxt .. _lockTxt
                pcall(_setPreview, _winner.name)
            else
                headerLbl.Text = "BEST BRAINROT"
                nameLbl.Text   = "no targets"
                genLbl.Text    = ""
                locLbl.Text    = ""
                pillStroke.Color       = Theme.Accent1
                pillStroke.Transparency = 0.3
                pcall(_setPreview, nil)
            end
            pill.BackgroundColor3 = Theme.Background
        end end) end)
