    _priBtn("EXPORT LIST", UDim2.new(0, 12, 1, -45), Theme.Accent1).MouseButton1Click:Connect(function() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        local isMut = (_pgMode == "mutation")
        local payload = isMut and { t = "mut", v = MUTATION_LIST } or PRIORITY_LIST
        local ok, json = pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
return HttpService:JSONEncode(payload) end)
        if not ok or not json then return end
        if setclipboard then pcall(setclipboard, json) end
        if writefile then pcall(writefile, isMut and "rosehub_mutation_export.json" or "rosehub_priority_export.json", json) end
        if priImportBox then priImportBox.Text = json end
    end)
    _priBtn("IMPORT LIST", UDim2.new(1, -112, 1, -45), Theme.Accent2).MouseButton1Click:Connect(function() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        local raw = priImportBox and priImportBox.Text or ""
        if raw == "" and getclipboard then local okc, c = pcall(getclipboard); if okc and type(c) == "string" then raw = c end end
        if raw == "" then return end
        local ok, decoded = pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
return HttpService:JSONDecode(raw) end)
        if not ok or type(decoded) ~= "table" then return end
        local isMut = (_pgMode == "mutation")
        if (decoded.t == "mut") ~= isMut then return end
        local arr = decoded
        if isMut then arr = decoded.v end
        if type(arr) ~= "table" then return end
        local newList = {}
        for _, v in ipairs(arr) do if type(v) == "string" then newList[#newList + 1] = v end end
        if #newList == 0 then return end
        if isMut then
            local seen, merged, inRoster = {}, {}, {}
            for _, m in ipairs(mutRoster) do inRoster[m.name] = true end
            for _, v in ipairs(newList) do if inRoster[v] and not seen[v] then seen[v] = true; merged[#merged + 1] = v end end
            for _, m in ipairs(mutRoster) do if not seen[m.name] then seen[m.name] = true; merged[#merged + 1] = m.name end end
            newList = merged
        end
        local LIST = _curList()
        for idx = #LIST, 1, -1 do LIST[idx] = nil end
        for _, v in ipairs(newList) do LIST[#LIST + 1] = v end
        _curSave(); refreshPriorityList(); refreshAvailableList()
        if priImportBox then priImportBox.Text = "" end
    end)
