    _indexTabRows = function(sc) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        if not sc then return end
        for _, ch in ipairs(sc:GetChildren()) do
            if ch:IsA("Frame") and ch.Visible and ch.Size.Y.Offset >= 32 and not ch:GetAttribute("JAFNoSearch") then
                local tl = ch:FindFirstChildOfClass("TextLabel")
                if tl and tl.Text ~= "" then
                    searchRegistry[#searchRegistry+1] = { row = ch, origParent = sc, origOrder = ch.LayoutOrder, label = string.lower(tl.Text) }
                end end end end
    for id, sc in pairs(tScrolls2) do if _tabBuilt[id] then _indexTabRows(sc) end end
    local function fuzzyMatch(hay, needle) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        if needle == "" then return true end
        if string.find(hay, needle, 1, true) then return true end
        local hi, ni = 1, 1
        local hlen, nlen = #hay, #needle
        while hi <= hlen and ni <= nlen do if string.byte(hay, hi) == string.byte(needle, ni) then ni = ni + 1 end hi = hi + 1 end
        return ni > nlen
    end
    local function restoreMoved() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        for _, e in ipairs(searchMoved) do e.row.LayoutOrder = e.origOrder e.row.Parent = e.origParent end
