        if not (_G.JAF_AutoBuyActive and _G.JAF_AutoBuyActive()) then _G.JAF_KickDbg = "autobuy-off"; return end
        if not entry then _G.JAF_KickDbg = "uuid-not-one-we-bought"; return end
        if baseIndex and entry.index and tostring(entry.index) ~= tostring(baseIndex) then _G.JAF_KickDbg = "name-mismatch"; return end
        if not entry.close then _G.JAF_KickDbg = "not-within-7-of-brainrot"; return end
        _G.JAF_KickDbg = "KICK"
        if carpetBuyOn and didFirstTp then setArrivedBuy(false) end
        doKickAfterBuy()
    end
    if _G.JAF_NoSynchronizer ~= true then task.spawn(function() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        local chFolder = RSvc:WaitForChild("Packages"):WaitForChild("Synchronizer"):WaitForChild("Channel")
        local cachedName
        local function _chIsOurs(data) LPH_ATTRIBUTES(ERROR_HANDLING(false))
            local ok, own = pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
return data:Get("Owner") end)
            return ok and own ~= nil and tostring(own) == LocalPlayer.Name
        end
        local function readOurAnimalList() LPH_ATTRIBUTES(ERROR_HANDLING(false))
            local Sync = getSync(); if not Sync then return nil end
            if cachedName then
                local ok, data = pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
return Sync:Get(cachedName) end)
                if ok and data and _chIsOurs(data) then
                    local ok2, al = pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
return data:Get("AnimalList") end)
                    if ok2 and type(al) == "table" then return al end
                end
                cachedName = nil
            end
            for _, ch in ipairs(chFolder:GetChildren()) do
                if ch:IsA("RemoteEvent") and #ch.Name == 36 and ch.Name:find("%-") then
                    local ok, data = pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
return Sync:Get(ch.Name) end)
                    if ok and data and _chIsOurs(data) then
                        local ok2, al = pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
return data:Get("AnimalList") end)
                        if ok2 and type(al) == "table" then cachedName = ch.Name; return al end
                    end end end
            return nil
        end
        local seen
        while true do
            RunService.Heartbeat:Wait()
            if kickFired then break end
            local al = readOurAnimalList()
            if type(al) == "table" then
                local now = {}
                local freshUuid, freshIndex, freshEntry
                for _, e in pairs(al) do
                    if type(e) == "table" and e.UUID then
                        now[e.UUID] = true
                        if seen and not seen[e.UUID] then
                            freshUuid = tostring(e.UUID)
                            freshIndex = e.Index ~= nil and tostring(e.Index) or nil
                            freshEntry = e
                        end end end
                if freshUuid then
                    local rb = _G.JAF_RecentBuys
                    local boughtEntry = rb and rb[freshUuid] or nil
                    tryKickAfterBuy(boughtEntry, freshIndex)
                end
                seen = now
            end end
    end) end
    if Config.CarpetAutoBuy then task.defer(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
pcall(_G.JAF_ToggleCarpetBuy, true) end) end
end end
task.spawn(function() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
    if _G.JAF_NoCarpetScan == true then return end
    _G.JAF_WaitHeavy()
    local MUT_COL = {
        gold = Color3.fromRGB(255,215,0),     diamond = Color3.fromRGB(0,225,255),
        rainbow = Color3.fromRGB(255,120,220), candy = Color3.fromRGB(255,105,180),
        cursed = Color3.fromRGB(210,45,45),    bloodrot = Color3.fromRGB(150,0,0),
        lava = Color3.fromRGB(255,110,20),     radioactive = Color3.fromRGB(120,255,0),
        divine = Color3.fromRGB(255,250,205),  yinyang = Color3.fromRGB(235,235,235),
        galaxy = Color3.fromRGB(170,85,255),
    }
    local MUT_KW = {"Galaxy","Bloodrot","Radioactive","Rainbow","Diamond","Divine","YinYang","Cursed","Candy","Lava","Gold"}
    local function detectMutation(model) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        if not model then return nil end
        local hit = nil
        pcall(function() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
            for _, d in ipairs(model:GetDescendants()) do
                if d:IsA("TextLabel") and type(d.Text) == "string" and d.Text ~= "" then
                    local low = d.Text:lower()
                    for _, kw in ipairs(MUT_KW) do if low:find(kw:lower(), 1, true) then hit = kw; return end end
                end end end)
        return hit
    end
    local function partOf(entry) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        local m = entry and entry.model
        if not m or not m.Parent then return nil end
        if m:IsA("BasePart") then return m end
        return m.PrimaryPart or m:FindFirstChildWhichIsA("BasePart", true)
    end
    local espFolder, bill
    local _mutCache = setmetatable({}, { __mode = "k" })
    local function cachedMutation(model) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        if not model then return nil end
        local c = _mutCache[model]
        if c ~= nil then return c or nil end
        local m = detectMutation(model)
        _mutCache[model] = m or false
        return m
    end
    local function clear() LPH_ATTRIBUTES(ERROR_HANDLING(false))
if bill then pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
bill:Destroy() end); bill = nil end end
    while true do
        task.wait(0.4)
        if not Config.ConveyorESP then
            clear()
        else
            local best, bestGv, bestPart = nil, -math.huge, nil
            for _, w in ipairs(SharedState.WalkingCache or {}) do
                if w and w.genValue and w.genValue > bestGv then
                    local pp = partOf(w)
                    if pp then best, bestGv, bestPart = w, w.genValue, pp end
                end end
            local bestBaseGen = -math.huge
            for _, a in ipairs(SharedState.AllAnimalsCache or {}) do
                if a and a.genValue and a.owner ~= LocalPlayer.Name then if a.genValue > bestBaseGen then bestBaseGen = a.genValue end end
            end
            if not best or not bestPart or bestGv <= bestBaseGen then
                clear()
            else
                if not espFolder or not espFolder.Parent then
                    espFolder = Instance.new("Folder", Workspace); espFolder.Name = "JustAFanConveyorESP"
                end
                if not bill or not bill.Parent then
                    bill = Instance.new("BillboardGui")
                    bill.Name = "CarpetBestESP"; bill.Size = UDim2.new(0, 196, 0, 56)
                    bill.StudsOffset = Vector3.new(0, 3.5, 0); bill.AlwaysOnTop = true
                    bill.LightInfluence = 0; bill.MaxDistance = 100000; bill.Parent = espFolder
                    local root = Instance.new("Frame", bill); root.Name = "Root"; root.Size = UDim2.new(1,0,1,0)
                    root.BackgroundColor3 = Theme.Background; root.BackgroundTransparency = 0.25; root.BorderSizePixel = 0
                    Instance.new("UICorner", root).CornerRadius = UDim.new(0, 9)
                    local st = JUI.new("UIStroke", root, "Thickness", 1.6, "Color", Color3.fromRGB(255,215,0), "Transparency", 0.15); st.Name = "St"
                    local badge = Instance.new("TextLabel", root); badge.Name = "Badge"
                    badge.Size = UDim2.new(1,-10,0,12); badge.Position = UDim2.new(0,6,0,4); badge.BackgroundTransparency = 1
                    badge.Font = Enum.Font.GothamBlack; badge.TextSize = 9; badge.TextColor3 = Color3.fromRGB(255,215,0)
                    badge.TextXAlignment = Enum.TextXAlignment.Left; badge.Text = "BEST"
                    local nm = Instance.new("TextLabel", root); nm.Name = "Nm"
                    nm.Size = UDim2.new(1,-12,0,18); nm.Position = UDim2.new(0,6,0,16); nm.BackgroundTransparency = 1
                    nm.Font = Enum.Font.GothamBold; nm.TextSize = 14; nm.TextColor3 = Theme.TextPrimary
                    nm.TextXAlignment = Enum.TextXAlignment.Left; nm.TextTruncate = Enum.TextTruncate.AtEnd
                    local gn = Instance.new("TextLabel", root); gn.Name = "Gn"
                    gn.Size = UDim2.new(1,-12,0,14); gn.Position = UDim2.new(0,6,0,36); gn.BackgroundTransparency = 1
                    gn.Font = Enum.Font.GothamBlack; gn.TextSize = 13; gn.TextColor3 = Color3.fromRGB(90,225,140)
                    gn.TextXAlignment = Enum.TextXAlignment.Left
                end
                bill.Adornee = bestPart
                local root = bill:FindFirstChild("Root")
                if root then
                    local mut = cachedMutation(best.model)
                    local mcol = (mut and MUT_COL[mut:lower()]) or Theme.TextPrimary
                    local nm = root:FindFirstChild("Nm")
                    if nm then
                        nm.TextColor3 = mcol
                        nm.Text = mut and (mut .. " " .. tostring(best.name or "Brainrot")) or tostring(best.name or "Brainrot")
                    end
                    local gn = root:FindFirstChild("Gn"); if gn then gn.Text = tostring(best.genText or "") end
                    local st = root:FindFirstChild("St"); if st then st.Color = (mut and mcol) or Color3.fromRGB(255,215,0) end
                end end end end end)
task.spawn(function() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
    local ASC_Players = game:GetService("Players")
    local ASC_LP      = ASC_Players.LocalPlayer
    local BIG = 10
    local CLOTHING = { TShirt = true, Shirt = true, Sweater = true, Jacket = true, DressSkirt = true, Pants = true, Shorts = true, }
    local isBig; isBig = (function(p) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        if not p:IsA("BasePart") then return false end
        local s = p.Size
        return s.X > BIG or s.Y > BIG or s.Z > BIG
    end)
    local function hideBig(p) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        pcall(function() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
            _P(p, "Transparency", 1, "Transparency", 1, "CanCollide", false, "CanQuery", false, "CanTouch", false, "CastShadow", false)
        end) end
    local accCovers; accCovers = (function(acc) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        local tn
        pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
tn = acc.AccessoryType and acc.AccessoryType.Name end)
        if tn and CLOTHING[tn] then return true end
        for _, p in ipairs(acc:GetDescendants()) do if isBig(p) then return true end end
        return false
    end)
    local function nuke(obj) LPH_ATTRIBUTES(ERROR_HANDLING(false))
pcall(function() LPH_ATTRIBUTES(ERROR_HANDLING(false))
obj:Destroy() end) end
    local function isOtherChar(char) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        local plr = ASC_Players:GetPlayerFromCharacter(char)
        return plr ~= nil and plr ~= ASC_LP
    end
    local scrub; scrub = (function(char) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        if not char or not isOtherChar(char) then return end
        for _, obj in ipairs(char:GetDescendants()) do
            if obj:IsA("Accessory") then
                if accCovers(obj) then nuke(obj) end
            elseif obj:IsA("BasePart") and obj.Name ~= "HumanoidRootPart"
                   and obj ~= char.PrimaryPart and isBig(obj) then
                hideBig(obj)
            end end end)
    local function watch(char) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        if not isOtherChar(char) then return end
        scrub(char)
        char.ChildAdded:Connect(function(obj) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
            task.defer(function() LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
                if not obj.Parent then return end
                if obj:IsA("Accessory") then
                    if accCovers(obj) then nuke(obj) end
                elseif obj:IsA("BasePart") and obj.Name ~= "HumanoidRootPart" and isBig(obj) then
                    hideBig(obj)
                end end) end) end
    local function hookPlayer(plr) LPH_ATTRIBUTES(VM(NONE), ERROR_HANDLING(false))
        if plr == ASC_LP then return end
        if plr.Character then watch(plr.Character) end
        plr.CharacterAdded:Connect(watch)
    end
    for _, plr in ipairs(ASC_Players:GetPlayers()) do hookPlayer(plr) end
    ASC_Players.PlayerAdded:Connect(hookPlayer)
    while true do
        for _, plr in ipairs(ASC_Players:GetPlayers()) do if plr ~= ASC_LP and plr.Character then pcall(scrub, plr.Character) end end
        task.wait(1)
    end end)
